/** 속성 이름과 언어로 한 줄 설명을 꺼낸다 */
export function propDesc(name: string, lang: string): string {
  const row = CSS_DESC[name];
  if (!row) return '';
  const i = LANG_ORDER.indexOf(lang as (typeof LANG_ORDER)[number]);
  return row[i >= 0 ? i : 1];
}
